pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _value, bytes memory _data) public {
        vm.deal(address(this), 1 wei);
        (bool sent, ) = address(c).call{value: 1 wei}("");
        require(sent, "fallback failed");
        uint256 depositsBefore = c.depositsCount();
        require(depositsBefore > 0, "depositsCount must be > 0");

        vm.assume(_value <= address(c).balance);

        try c.sendMoney(_target, _value, _data) {
            uint256 depositsAfter = c.depositsCount();
            assertTrue(depositsAfter > 0);
        } catch {
        }
    }
}
